import XCTest
import Statelessness

// Source-authored N07 integration cases. No fixtures are generated by these tests.
// Use the real Recorder, sealed checking APIs, wire codec and public replay API.
// The application owns reducer/effect execution; diagnostics receive its result.
private final class ObservationIntegrationProbe {
    var initialCalls = 0
    var reducerCalls = 0
    var stateCalls = 0
    var transitionCalls = 0
    var effectCalls = 0
    var inputEncodes = 0
    var outputEncodes = 0
    var stateEncodes = 0
    var encodeFailure: String?
    var effects: [Int] = []
    let failAt: Int?

    init(failAt: Int? = nil) { self.failAt = failAt }
    var work: [Int] { [initialCalls, reducerCalls, stateCalls, transitionCalls, effectCalls] }
    var encodes: [Int] { [inputEncodes, outputEncodes, stateEncodes] }

    // Fixed-width signed values allow long sessions and rejected negative inputs.
    static func bytes(_ value: Int) -> [UInt8] {
        let bits = UInt32(bitPattern: Int32(value))
        return (0..<4).map { UInt8(truncatingIfNeeded: bits >> ($0 * 8)) }
    }
    static func value(_ bytes: [UInt8]) throws -> Int {
        guard bytes.count == 4 else { throw ModelError("four-byte counter required") }
        var bits: UInt32 = 0
        for (index, byte) in bytes.enumerated() { bits |= UInt32(byte) << (index * 8) }
        return Int(Int32(bitPattern: bits))
    }
    static func stateChecks(_ state: Int, failAt: Int? = nil) -> [Check] {
        var checks: [Check] = [.passed("state-\(state)")]
        if state.isMultiple(of: 2) { checks.append(.passed("even-\(state)")) }
        if let failAt, state >= failAt { checks.append(.failed("state.bound", "bound reached")) }
        return checks
    }
    func model() -> Model<Int, Int, Int> {
        Model(initialState: {
            self.initialCalls += 1
            throw ModelError("use the application checkpoint")
        }, step: { state, input in
            self.reducerCalls += 1
            if input == 0 { return Transition(state: state, disposition: .ignored("duplicate")) }
            if input < 0 { return Transition(state: state, outputs: [state * 10], disposition: .rejected("negative")) }
            let next = state + input
            return Transition(state: next, outputs: [next * 10, next * 10 + 1])
        }, checkState: { state in
            self.stateCalls += 1
            return Self.stateChecks(state, failAt: self.failAt)
        }, cloneState: { $0 }, cloneInput: { $0 }, cloneOutput: { $0 }, checkTransition: { _, input, turn in
            self.transitionCalls += 1
            let expected = input > 0 ? [turn.state * 10, turn.state * 10 + 1] : input == 0 ? [] : [turn.state * 10]
            var checks: [Check] = [turn.outputs == expected ? .passed("edge.outputs") : .failed("edge.outputs", "unexpected application outputs")]
            if input == 0 { checks.append(.skipped("edge.optional", "no output")) }
            return checks
        }, codec: Codec(metadata: { Metadata(name: "observation-recorder-integration", build: "source-v1") }, encodeState: { state in
            self.stateEncodes += 1
            if self.encodeFailure == "state" { throw ModelError("state encoder unavailable") }
            return Self.bytes(state)
        }, decodeState: Self.value, encodeInput: { input in
            self.inputEncodes += 1
            if self.encodeFailure == "input" { throw ModelError("input encoder unavailable") }
            return Self.bytes(input)
        }, decodeInput: Self.value, encodeOutput: { output in
            self.outputEncodes += 1
            if self.encodeFailure == "output" { throw ModelError("output encoder unavailable") }
            return Self.bytes(output)
        }))
    }
    func execute(_ model: Model<Int, Int, Int>, state: inout Int, input: Int,
                 sequence: UInt64, policy: CheckPolicy = CheckPolicy()) throws -> CheckedTurn<Int, Int, Int> {
        let before = state
        let actual = try model.step(before, input) // Exactly one application execution.
        for output in actual.outputs { effectCalls += 1; effects.append(output) }
        state = actual.state
        return try checkTurn(model, before: before, input: input, transition: actual, sequence: sequence, policy: policy)
    }
}

// Recorder admission tests supply application results directly. Callback logs
// distinguish early count rejection from later candidate/retention rejection.
private final class ObservationRecorderLimitProbe {
    var calls: [String] = []
    var failures: Set<String> = []
    var failedStateCheck = false

    private func called(_ stage: String) throws {
        calls.append(stage)
        if failures.contains(stage) { throw ModelError("\(stage) unavailable") }
    }
    func model() -> Model<Int, Int, Int> {
        Model(initialState: {
            try self.called("initial state")
            throw ModelError("use supplied checkpoint")
        }, step: { _, _ in
            try self.called("reducer")
            throw ModelError("use supplied transition")
        }, checkState: { _ in
            try self.called("check state")
            return [self.failedStateCheck ? .failed("state", "failed checkpoint") : .passed("state")]
        }, cloneState: { $0 }, cloneInput: { $0 }, cloneOutput: { $0 }, checkTransition: { _, _, _ in
            try self.called("check transition")
            return [.passed("edge")]
        }, codec: Codec(metadata: {
            try self.called("metadata")
            return Metadata(name: "recorder-limits", build: "source-v1")
        }, encodeState: { state in
            try self.called("encode state")
            return ObservationIntegrationProbe.bytes(state)
        }, decodeState: ObservationIntegrationProbe.value, encodeInput: { input in
            try self.called("encode input")
            return ObservationIntegrationProbe.bytes(input)
        }, decodeInput: ObservationIntegrationProbe.value, encodeOutput: { output in
            try self.called("encode output")
            return ObservationIntegrationProbe.bytes(output)
        }))
    }
}

private func integrationEvent(_ token: CheckedTurn<Int, Int, Int>) throws -> Event<Int, Int, Int> {
    let view = try token.observation()
    return .transition(sequence: try ObservationSequence(view.sequence), before: view.before,
                       input: view.input, transition: view.transition, checks: view.checks)
}

// A nonretaining destination lets the long-session test bound logical record
// bytes without confusing an application's accumulating log sink with the ring.
private final class ObservationIntegrationCountingWriter: ObservationWriter {
    var records = 0
    var largestRecord = 0
    var bytes: UInt64 = 0
    func write(_ bytes: ArraySlice<UInt8>) throws -> Int {
        records += 1; largestRecord = max(largestRecord, bytes.count)
        self.bytes += UInt64(bytes.count)
        return bytes.count
    }
    func flush() throws {}
}

private final class ObservationIntegrationFailingWriter: ObservationWriter {
    var bytes: [UInt8] = []
    var failAfter: Int?
    var failFlush = false
    var writes = 0
    var flushes = 0
    func write(_ bytes: ArraySlice<UInt8>) throws -> Int {
        writes += 1
        let count = min(bytes.count, failAfter.map { max(0, $0 - self.bytes.count) } ?? bytes.count)
        guard count > 0 else { throw ModelError("sink write failed") }
        self.bytes.append(contentsOf: bytes.prefix(count))
        return count
    }
    func flush() throws {
        flushes += 1
        if failFlush { throw ModelError("sink flush failed") }
    }
}

private final class ObservationIntegrationFormatFault { var stage: String? }
private struct ObservationIntegrationPayloads: PayloadFormat {
    typealias State = Int
    typealias Input = Int
    typealias Output = Int
    let fault: ObservationIntegrationFormatFault
    private func format(_ stage: String, value: Int, into out: ObservationBuffer) throws {
        try out.write("value:\(value)")
        if fault.stage == stage { throw ModelError("formatter \(stage) failed") }
        if stage == "input", fault.stage == "swallow" {
            // An ignored admission error must still reject the entire record.
            do { try out.write(String(repeating: "x", count: 4096)) } catch {}
        }
    }
    func state(_ model: Model<Int, Int, Int>, _ state: Int, into out: ObservationBuffer) throws { try format("state", value: state, into: out) }
    func input(_ model: Model<Int, Int, Int>, _ input: Int, into out: ObservationBuffer) throws { try format("input", value: input, into: out) }
    func output(_ model: Model<Int, Int, Int>, _ output: Int, into out: ObservationBuffer) throws { try format("output", value: output, into: out) }
}

final class ObservationRecorderIntegrationTests: XCTestCase {
    private typealias Probe = ObservationIntegrationProbe
    private typealias Log = TextObserver<ObservationBytes, EncodedPayloads<Int, Int, Int>>
    private let config = RunConfig(strategy: "application-owned")

    private func logger(_ level: LogLevel = .trace, snapshots: SnapshotPolicy = .everyTransition) throws -> Log {
        try Log(writer: ObservationBytes(), streamID: "app", options: ObservationOptions(level: level, snapshots: snapshots),
                payloads: EncodedPayloads(maxBlobBytes: 4))
    }
    private func text(_ log: Log) throws -> String { String(decoding: try log.getRef().bytes, as: UTF8.self) }
    private func parameter(_ trace: AuditTrace, _ name: String) -> String? {
        trace.config.parameters.first { $0.key == "stateless.monitor.\(name)" }?.value
    }
    private func assertStage(_ expected: TextObservationError.Stage, _ operation: () throws -> Void,
                             file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertThrowsError(try operation(), file: file, line: line) { error in
            guard let error = error as? TextObservationError else { return XCTFail("unexpected error: \(error)", file: file, line: line) }
            XCTAssertEqual(error.stage.rawValue, expected.rawValue, file: file, line: line)
        }
    }
    private func assertRecorderError(_ expected: String, _ operation: () throws -> Void,
                                     file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertThrowsError(try operation(), file: file, line: line) { error in
            guard let error = error as? ModelError else { return XCTFail("unexpected error: \(error)", file: file, line: line) }
            XCTAssertEqual(error.description, expected, file: file, line: line)
        }
    }
    private func assertSamePrefix(_ actual: AuditTrace, _ expected: AuditTrace,
                                  file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertEqual(actual.metadata, expected.metadata, file: file, line: line)
        XCTAssertEqual(actual.config, expected.config, file: file, line: line)
        XCTAssertEqual(actual.initialState, expected.initialState, file: file, line: line)
        XCTAssertEqual(actual.initialChecks, expected.initialChecks, file: file, line: line)
        XCTAssertEqual(actual.steps, expected.steps, file: file, line: line)
    }
    private func assertReplay(_ trace: AuditTrace, failAt: Int? = nil, failure: Bool = false,
                              file: StaticString = #filePath, line: UInt = #line) throws {
        let bytes = try encodeAuditTrace(trace)
        let restored = try decodeAuditTrace(bytes)
        XCTAssertEqual(restored, trace, file: file, line: line)
        let playback = Probe(failAt: failAt)
        var sequences: [UInt64] = [], initialObservations = 0
        let report = try replayWithObservationsBounded(playback.model(), trace: restored) { observation, _ in
            switch observation {
            case let .initial(value):
                initialObservations += 1
                XCTAssertEqual(value.actualState, restored.initialState, file: file, line: line)
                XCTAssertEqual(value.checks, restored.initialChecks, file: file, line: line)
                XCTAssertTrue(value.differences.isEmpty, file: file, line: line)
            case let .turn(value):
                sequences.append(value.sequence)
                XCTAssertTrue(value.differences.isEmpty, file: file, line: line)
                XCTAssertEqual(value.actualOutputs, value.expected.outputs, file: file, line: line)
                XCTAssertEqual(value.checks, value.expected.checks, file: file, line: line)
            case .error: XCTFail("retained suffix replay errored", file: file, line: line)
            }
        }
        XCTAssertEqual(report.outcome, "exact", file: file, line: line)
        XCTAssertEqual(report.stepsVerified, trace.steps.count, file: file, line: line)
        XCTAssertEqual(report.failureReproduced, failure, file: file, line: line)
        XCTAssertTrue(report.buildMatches, file: file, line: line)
        XCTAssertEqual(initialObservations, 1, file: file, line: line)
        // The public replay API numbers the stored suffix locally. Origin and
        // evicted-prefix counts remain explicit recording metadata, not replayed history.
        XCTAssertEqual(sequences, trace.steps.indices.map { UInt64($0 + 1) }, file: file, line: line)
        XCTAssertEqual(playback.work, [0, trace.steps.count, trace.steps.count + 1, trace.steps.count, 0], file: file, line: line)
    }

    private struct Session {
        let state: Int
        let work: [Int]
        let encodes: [Int]
        let effects: [Int]
        let checks: [[Check]]
        let trace: AuditTrace?
        let text: String
    }
    private func session(record: Bool, level: LogLevel?) throws -> Session {
        let probe = Probe(failAt: 8), model = probe.model()
        var state = 4
        let initial = try checkInitial(model, state: state)
        let recorder: Recorder? = record ? try Recorder(checkedInitial: initial, sequenceOrigin: 10, config: config,
                                                       options: RecorderOptions(maxSteps: 8)) : nil
        let log: Log? = try level.map { try logger($0) }
        if let log { try log.observe(model, event: .checkpoint(sequence: 10, state: try initial.state, checks: initial.checks)) }
        var batches = [initial.checks]
        for (index, input) in [1, 0, -1, 2, 1].enumerated() {
            let token = try probe.execute(model, state: &state, input: input, sequence: UInt64(index + 11))
            batches.append(token.checks)
            let work = probe.work
            if let recorder { XCTAssertEqual(try recorder.observeChecked(token), token.checks) }
            if let log { try log.observe(model, event: integrationEvent(token)) }
            XCTAssertEqual(probe.work, work, "recording/logging repeated application work")
        }
        return Session(state: state, work: probe.work, encodes: probe.encodes, effects: probe.effects, checks: batches,
                       trace: recorder?.snapshot(), text: try log.map(text) ?? "")
    }

    func testEveryLogLevelMatchesUninstrumentedApplicationAndRecorderEvidence() throws {
        // No observer and no Recorder in this baseline. Production checking and
        // effects still run once, just as they do in instrumented sessions.
        let plain = try session(record: false, level: nil)
        XCTAssertEqual(plain.state, 8)
        XCTAssertEqual(plain.work, [0, 5, 6, 5, 7])
        XCTAssertEqual(plain.encodes, [0, 0, 0])
        XCTAssertEqual(plain.effects, [50, 51, 50, 70, 71, 80, 81])
        XCTAssertNil(plain.trace)
        let recorded = try session(record: true, level: nil)
        XCTAssertEqual(recorded.work, plain.work)
        XCTAssertEqual(recorded.effects, plain.effects)
        XCTAssertEqual(recorded.checks, plain.checks)
        XCTAssertEqual(recorded.encodes, [5, 7, 11]) // Initial + before/post encodes.
        let expected = try XCTUnwrap(recorded.trace)
        XCTAssertEqual(expected.termination, .propertyFailed)
        XCTAssertEqual(expected.steps.map(\.disposition), [.accepted, .ignored("duplicate"), .rejected("negative"), .accepted, .accepted])
        XCTAssertEqual(expected.steps.map(\.outputs), [[50, 51], [], [50], [70, 71], [80, 81]].map { $0.map(Probe.bytes) })
        XCTAssertEqual(expected.steps.map(\.checks), Array(plain.checks.dropFirst()))
        for level in LogLevel.allCases {
            let observed = try session(record: true, level: level)
            XCTAssertEqual(observed.state, plain.state, "\(level)")
            XCTAssertEqual(observed.work, plain.work, "\(level)")
            XCTAssertEqual(observed.effects, plain.effects, "\(level)")
            XCTAssertEqual(observed.checks, plain.checks, "\(level)")
            XCTAssertEqual(observed.trace, expected, "\(level)")
            XCTAssertEqual(observed.encodes, level == .trace ? [10, 14, 17] : recorded.encodes, "Trace alone adds input/output/selected-state encodes")
            let lines = observed.text.split(separator: "\n")
            let count: Int
            switch level { case .off: count = 0; case .error: count = 1; case .warn, .info: count = 2; case .debug: count = 5; case .trace: count = 6 }
            XCTAssertEqual(lines.count, count, "\(level)")
            if level != .off { XCTAssertTrue(lines.contains { $0.hasPrefix("Error ") && $0.contains("sequence=15") && $0.contains("state.bound\":Failed") }) }
            if level >= .warn { XCTAssertTrue(lines.contains { $0.hasPrefix("Warn ") && $0.contains("sequence=12") && $0.contains("edge.optional\":Skipped") }) }
            if level < .trace { XCTAssertFalse(observed.text.contains("hex:")); XCTAssertFalse(observed.text.contains(":Passed")) }
            else {
                XCTAssertTrue(observed.text.contains("output[0]=hex:50000000 output[1]=hex:51000000 post_state=hex:08000000"))
                XCTAssertTrue(observed.text.contains("disposition=Rejected(\"negative\") outputs=1"))
                XCTAssertTrue(observed.text.contains("disposition=Ignored(\"duplicate\") outputs=0"))
            }
        }
        try assertReplay(expected, failAt: 8, failure: true)
    }

    func testLongTinyWindowsPromoteOnlyStateChecksAndReplayExactSuffix() throws {
        for origin: UInt64 in [0, 1000] {
            for capacity in [1, 3] {
                let probe = Probe(), model = probe.model(), writer = ObservationIntegrationCountingWriter()
                var state = 4
                let initial = try checkInitial(model, state: state)
                let recorder = try Recorder(checkedInitial: initial, sequenceOrigin: origin, config: config,
                                            options: RecorderOptions(maxSteps: capacity, maxRetainedBytes: 4096))
                let log = try TextObserver(writer: writer, streamID: "long", options: ObservationOptions(level: .trace, snapshots: .every(7), maxRecordBytes: 1024), payloads: EncodedPayloads<Int, Int, Int>(maxBlobBytes: 4))
                try log.observe(model, event: .checkpoint(sequence: origin, state: try initial.state, checks: initial.checks))
                var last: CheckedTurn<Int, Int, Int>?
                for index in 1...1024 {
                    let token = try probe.execute(model, state: &state, input: 1, sequence: origin + UInt64(index))
                    let work = probe.work
                    try recorder.observeChecked(token)
                    try log.observe(model, event: integrationEvent(token))
                    XCTAssertEqual(probe.work, work)
                    XCTAssertEqual(recorder.observedSteps, UInt64(index))
                    XCTAssertEqual(recorder.retainedSteps, min(index, capacity))
                    XCTAssertEqual(recorder.evictedSteps, UInt64(max(0, index - capacity)))
                    XCTAssertLessThanOrEqual(try recorder.retainedBytes, 4096)
                    let trace = recorder.snapshot(), checkpoint = 4 + max(0, index - capacity)
                    XCTAssertEqual(trace.initialState, Probe.bytes(checkpoint))
                    XCTAssertEqual(trace.initialChecks, Probe.stateChecks(checkpoint))
                    XCTAssertFalse(trace.initialChecks.contains { $0.id.hasPrefix("edge.") })
                    XCTAssertEqual(parameter(trace, "checkpoint_after_sequence"), String(max(0, index - capacity)))
                    if [1, capacity, capacity + 1, 1024].contains(index) {
                        XCTAssertEqual(try recorder.retainedBytes, UInt64(try encodeAuditTrace(trace).count))
                        try assertReplay(trace)
                    }
                    last = token
                }
                let token = try XCTUnwrap(last)
                // Explicit checkpoint selection is independent of Every(7).
                try log.observe(model, event: .checkpoint(sequence: token.sequence, state: try token.transition.state,
                                                          checks: Array(token.checks.prefix(token.stateCheckCount))))
                let trace = recorder.snapshot()
                XCTAssertEqual(state, 1028)
                XCTAssertEqual(probe.work, [0, 1024, 1025, 1024, 2048])
                let selected = Int((origin + 1024) / 7 - origin / 7)
                XCTAssertEqual(probe.encodes, [2048, 4096, 2051 + selected])
                XCTAssertEqual(writer.records, 1026)
                XCTAssertLessThanOrEqual(writer.largestRecord, 1024)
                XCTAssertGreaterThan(writer.bytes, try recorder.retainedBytes)
                XCTAssertEqual(parameter(trace, "sequence_origin"), origin == 0 ? nil : String(origin))
                XCTAssertEqual(parameter(trace, "observed_steps"), "1024")
                XCTAssertEqual(parameter(trace, "evicted_steps"), String(1024 - capacity))
                XCTAssertEqual(parameter(trace, "checking"), "full")
                XCTAssertFalse(recorder.isFrozen)
            }
        }
    }

    func testZeroCapacityAndZeroSequencesAreRejectedWithoutApplicationWork() throws {
        let probe = Probe(), model = probe.model(), initial = try checkInitial(model, state: 4)
        let work = probe.work
        XCTAssertThrowsError(try Recorder(checkedInitial: initial, config: config, options: RecorderOptions(maxSteps: 0))) { error in
            XCTAssertTrue(String(describing: error).contains("max_steps must be positive"))
        }
        XCTAssertThrowsError(try ObservationSequence(0))
        XCTAssertThrowsError(try SnapshotPolicy.every(0))
        XCTAssertEqual(probe.work, work)
        XCTAssertEqual(probe.encodes, [0, 0, 0])
        let recorder = try Recorder(checkedInitial: initial, sequenceOrigin: UInt64.max - 1, config: config, options: RecorderOptions(maxSteps: 1))
        let log = try logger()
        var state = 4
        let last = try probe.execute(model, state: &state, input: 1, sequence: UInt64.max)
        try recorder.observeChecked(last)
        try log.observe(model, event: integrationEvent(last))
        XCTAssertTrue(try text(log).contains("sequence=18446744073709551615"))
        let prefix = recorder.snapshot()
        let wrapped = try probe.execute(model, state: &state, input: 1, sequence: 1)
        try log.observe(model, event: integrationEvent(wrapped))
        XCTAssertThrowsError(try recorder.observeChecked(wrapped))
        assertSamePrefix(recorder.snapshot(), prefix)
        XCTAssertEqual(recorder.observedSteps, 1)
        XCTAssertEqual(probe.work, [0, 2, 3, 2, 4])
    }

    func testReservedFooterPrecedesCheckpointEncodingAndCheckingButFollowsMetadata() throws {
        // src/monitor.rs validates reserved_end_size after metadata, even for
        // a failing checkpoint. The minimum error-footer payload is 13 bytes:
        // u64 count + u8 termination + u32 empty-string length (src/trace.rs).
        let cases: [(frame: UInt64, faults: Set<String>, failedCheck: Bool, error: String, calls: [String])] = [
            (0, ["encode state", "check state"], false, "runtime recording limit: trace exceeds frame bytes limit", ["metadata"]),
            (12, ["encode state", "check state"], false, "runtime recording limit: trace exceeds frame bytes limit", ["metadata"]),
            (12, ["check state"], false, "runtime recording limit: trace exceeds frame bytes limit", ["metadata"]),
            (12, [], true, "runtime recording limit: trace exceeds frame bytes limit", ["metadata"]),
            (12, ["metadata", "encode state", "check state"], false, "runtime recording: runtime metadata: metadata unavailable", ["metadata"]),
            (13, ["encode state", "check state"], false, "runtime recording: runtime encode checkpoint: encode state unavailable", ["metadata", "encode state"]),
            (13, ["check state"], false, "runtime recording: state check: check state unavailable", ["metadata", "encode state", "check state"]),
            // The footer now fits; the run frame still fails after callbacks.
            (13, [], false, "runtime recording limit: trace exceeds frame bytes limit", ["metadata", "encode state", "check state"])
        ]
        for test in cases {
            let probe = ObservationRecorderLimitProbe(), model = probe.model()
            probe.failures = test.faults; probe.failedStateCheck = test.failedCheck
            var limits = BinaryTraceLimits(); limits.maxFrameBytes = test.frame
            assertRecorderError(test.error) {
                _ = try Recorder(model: model, state: 4, config: config, options: RecorderOptions(maxSteps: 1, limits: limits))
            }
            XCTAssertEqual(probe.calls, test.calls, "frame=\(test.frame), faults=\(test.faults)")
        }
    }

    func testCheckedCheckpointFooterValidationDoesNotRecheckOrBypassReservation() throws {
        for failedCheck in [false, true] {
            let probe = ObservationRecorderLimitProbe(), model = probe.model()
            probe.failedStateCheck = failedCheck
            let initial = try checkInitial(model, state: 4)
            XCTAssertEqual(probe.calls, ["check state"])
            var limits = BinaryTraceLimits(); limits.maxFrameBytes = 12; limits.maxChecksPerStep = 0
            probe.calls = []; probe.failures = ["encode state", "check state"]
            assertRecorderError("runtime recording limit: trace exceeds frame bytes limit") {
                _ = try Recorder(checkedInitial: initial, config: config, options: RecorderOptions(maxSteps: 1, limits: limits))
            }
            XCTAssertEqual(probe.calls, ["metadata"])
            // Same authentic checkpoint remains reusable after failed admission.
            // A now-throwing checker must never be consulted by this constructor.
            probe.calls = []; probe.failures = ["check state"]
            let recorder = try Recorder(checkedInitial: initial, config: config, options: RecorderOptions(maxSteps: 1))
            XCTAssertEqual(probe.calls, ["metadata", "encode state"])
            XCTAssertEqual(recorder.snapshot().initialChecks, initial.checks)
            XCTAssertEqual(recorder.termination, failedCheck ? .propertyFailed : .interrupted)
        }
    }

    func testOutputCountLimitCategoriesPrecedeInputAndCheckCallbacks() throws {
        // Count-only admission follows continuity, then outputs-per-step,
        // aggregate items, and only then input encoding/checking in Rust.
        let cases: [(outputs: UInt64, items: UInt64, count: Int, category: String)] = [
            (64, 128, 65, "outputs per step"),
            (128, 64, 65, "aggregate items"),
            (64, 64, 65, "outputs per step"),
            (0, 64, 1, "outputs per step")
        ]
        for checked in [false, true] {
            for test in cases {
                let probe = ObservationRecorderLimitProbe(), model = probe.model()
                var limits = BinaryTraceLimits(); limits.maxOutputsPerStep = test.outputs; limits.maxItems = test.items
                let recorder = try Recorder(model: model, state: 4, config: config, options: RecorderOptions(maxSteps: 1, limits: limits))
                let prefix = recorder.snapshot()
                let turn = Transition(state: 5, outputs: Array(repeating: 7, count: test.count))
                let token = checked ? try checkTurn(model, before: 4, input: 1, transition: turn, sequence: 1) : nil
                probe.calls = []; probe.failures = ["encode input", "check state", "check transition", "encode output"]
                let expected = "runtime recording limit: trace exceeds \(test.category) limit"
                assertRecorderError(expected) {
                    if let token { try recorder.observeChecked(token) }
                    else { try recorder.observe(model: model, before: 4, input: 1, transition: turn) }
                }
                XCTAssertEqual(probe.calls, ["metadata", "encode state"])
                assertSamePrefix(recorder.snapshot(), prefix)
                XCTAssertEqual(recorder.observedSteps, 0)
                XCTAssertEqual(recorder.evictedSteps, 0)
                XCTAssertEqual(recorder.termination, .modelError(expected))
                XCTAssertTrue(recorder.isFrozen)
            }
        }
    }

    func testOutputCountEqualityReachesInputAndContinuityStillWins() throws {
        for checked in [false, true] {
            for discontinuous in [false, true] {
                for count in [64, 65] {
                    let probe = ObservationRecorderLimitProbe(), model = probe.model()
                    var limits = BinaryTraceLimits(); limits.maxOutputsPerStep = 64; limits.maxItems = 64
                    let recorder = try Recorder(model: model, state: 4, config: config, options: RecorderOptions(maxSteps: 1, limits: limits))
                    let prefix = recorder.snapshot(), before = discontinuous ? 3 : 4
                    let turn = Transition(state: 5, outputs: Array(repeating: 7, count: count))
                    let token = checked ? try checkTurn(model, before: before, input: 1, transition: turn, sequence: 1) : nil
                    probe.calls = []; probe.failures = ["encode input", "check state", "check transition", "encode output"]
                    let expected = discontinuous ? "runtime before state is discontinuous; observations are missing or reordered"
                        : count == 65 ? "runtime recording limit: trace exceeds outputs per step limit"
                        : "runtime encode input: encode input unavailable"
                    assertRecorderError(expected) {
                        if let token { try recorder.observeChecked(token) }
                        else { try recorder.observe(model: model, before: before, input: 1, transition: turn) }
                    }
                    XCTAssertEqual(probe.calls, ["metadata", "encode state"] + (!discontinuous && count == 64 ? ["encode input"] : []))
                    assertSamePrefix(recorder.snapshot(), prefix)
                    XCTAssertEqual(recorder.termination, .modelError(expected))
                }
            }
        }
    }

    func testOutputAndAggregateItemBoundariesIncludeChecksAndRetainedRun() throws {
        // Source accounting: 8 stamped parameters + 1 checkpoint check = 9
        // run items. Each step adds 1 step + 2 checks + N outputs. At maxItems
        // 64, N=52 fits exactly and N=53 fails only after complete encoding;
        // N=62 fails within the step before output/post-state encoding.
        let cases: [(count: Int, outputs: UInt64, items: UInt64, fits: Bool, encodesOutputs: Bool)] = [
            (0, 0, 64, true, true), (64, 64, 128, true, true),
            (52, 128, 64, true, true), (53, 128, 64, false, true),
            (62, 128, 64, false, false), (64, 128, 64, false, false)
        ]
        for checked in [false, true] {
            for test in cases {
                let probe = ObservationRecorderLimitProbe(), model = probe.model()
                var limits = BinaryTraceLimits(); limits.maxOutputsPerStep = test.outputs; limits.maxItems = test.items
                let recorder = try Recorder(model: model, state: 4, config: config, options: RecorderOptions(maxSteps: 2, limits: limits))
                let prefix = recorder.snapshot(), turn = Transition(state: 5, outputs: Array(repeating: 7, count: test.count))
                let token = checked ? try checkTurn(model, before: 4, input: 1, transition: turn, sequence: 1) : nil
                probe.calls = []
                if checked { probe.failures = ["check state", "check transition"] }
                let capture = {
                    if let token { _ = try recorder.observeChecked(token) }
                    else { _ = try recorder.observe(model: model, before: 4, input: 1, transition: turn) }
                }
                if test.fits { try capture() }
                else { assertRecorderError("runtime recording limit: trace exceeds aggregate items limit", capture) }
                let expectedCalls = ["metadata", "encode state", "encode input"]
                    + (checked ? [] : ["check state", "check transition"])
                    + (test.encodesOutputs ? Array(repeating: "encode output", count: test.count) + ["encode state"] : [])
                XCTAssertEqual(probe.calls, expectedCalls)
                XCTAssertEqual(recorder.observedSteps, test.fits ? 1 : 0)
                XCTAssertEqual(recorder.evictedSteps, 0)
                if test.fits {
                    let step = try XCTUnwrap(recorder.snapshot().steps.first)
                    XCTAssertEqual(step.outputs, Array(repeating: Probe.bytes(7), count: test.count))
                    XCTAssertEqual(step.checks, [.passed("state"), .passed("edge")])
                    XCTAssertFalse(recorder.isFrozen)
                } else {
                    assertSamePrefix(recorder.snapshot(), prefix)
                    XCTAssertTrue(recorder.isFrozen)
                }
            }
        }
    }

    func testAggregateItemBudgetEvictsOnlyAfterCandidateCanFit() throws {
        let probe = ObservationRecorderLimitProbe(), model = probe.model()
        var limits = BinaryTraceLimits(); limits.maxItems = 64; limits.maxOutputsPerStep = 128
        let initial = try checkInitial(model, state: 4)
        let recorder = try Recorder(checkedInitial: initial, config: config, options: RecorderOptions(maxSteps: 2, limits: limits))
        for sequence in [UInt64(1), 2] {
            let before = 3 + Int(sequence)
            let turn = Transition(state: before + 1, outputs: Array(repeating: 7, count: 52))
            let token = try checkTurn(model, before: before, input: 1, transition: turn, sequence: sequence)
            probe.calls = []
            try recorder.observeChecked(token)
            XCTAssertEqual(probe.calls, ["metadata", "encode state", "encode input"] + Array(repeating: "encode output", count: 52) + ["encode state"])
            XCTAssertEqual(recorder.observedSteps, sequence)
            XCTAssertEqual(recorder.retainedSteps, 1)
            XCTAssertEqual(recorder.evictedSteps, sequence - 1)
            XCTAssertEqual(recorder.snapshot().initialState, Probe.bytes(before))
            XCTAssertEqual(recorder.snapshot().initialChecks, [.passed("state")])
        }
        let prefix = recorder.snapshot()
        let oversized = try checkTurn(model, before: 6, input: 1, transition: Transition(state: 7, outputs: Array(repeating: 7, count: 53)), sequence: 3)
        assertRecorderError("runtime recording limit: trace exceeds aggregate items limit") { try recorder.observeChecked(oversized) }
        assertSamePrefix(recorder.snapshot(), prefix)
        XCTAssertEqual(recorder.observedSteps, 2)
        XCTAssertEqual(recorder.evictedSteps, 1)
        XCTAssertEqual(recorder.retainedSteps, 1)
        XCTAssertTrue(recorder.isFrozen)
        let frozen = recorder.snapshot(), calls = probe.calls
        assertRecorderError("runtime recorder is frozen; export its retained trace") { try recorder.observeChecked(oversized) }
        try recorder.stopWithError(ModelError("later failure"))
        XCTAssertEqual(probe.calls, calls)
        XCTAssertEqual(recorder.snapshot(), frozen)
    }

    func testPeriodicAndDisabledChecksCannotCertifyExactRecorder() throws {
        let policies = [CheckPolicy(stateEvery: 4), CheckPolicy(stateEvery: 2), CheckPolicy(transitionChecks: false)]
        for (index, policy) in policies.enumerated() {
            let probe = Probe(), model = probe.model(), initial = try checkInitial(model, state: 4)
            let recorder = try Recorder(checkedInitial: initial, sequenceOrigin: 40, config: config, options: RecorderOptions(maxSteps: 1))
            let log = try logger(.debug)
            var state = 4
            let first = try probe.execute(model, state: &state, input: 1, sequence: 41)
            try recorder.observeChecked(first)
            try log.observe(model, event: integrationEvent(first))
            let prefix = recorder.snapshot()
            let sampled = try probe.execute(model, state: &state, input: 1, sequence: 42, policy: policy)
            XCTAssertFalse(sampled.fullChecking)
            let expected: [Check]
            switch index {
            case 0: expected = [.skipped("stateless.state_checks", "periodic checking policy"), .passed("edge.outputs")]
            case 1: expected = [.passed("state-6"), .passed("even-6"), .passed("edge.outputs")]
            default: expected = [.passed("state-6"), .passed("even-6"), .skipped("stateless.transition_checks", "disabled by policy")]
            }
            XCTAssertEqual(sampled.checks, expected)
            XCTAssertEqual(sampled.stateCheckCount, index == 0 ? 1 : 2)
            let work = probe.work
            try log.observe(model, event: integrationEvent(sampled))
            XCTAssertThrowsError(try recorder.observeChecked(sampled)) { error in
                XCTAssertTrue(String(describing: error).contains("requires full checking"))
            }
            XCTAssertEqual(probe.work, work)
            XCTAssertEqual(probe.work, [0, 2, index == 0 ? 2 : 3, index == 2 ? 1 : 2, 4])
            let lastLine = try XCTUnwrap(text(log).split(separator: "\n").last)
            XCTAssertTrue(lastLine.hasPrefix(index == 1 ? "Debug " : "Warn "))
            assertSamePrefix(recorder.snapshot(), prefix)
            XCTAssertEqual(recorder.evictedSteps, 0)
            XCTAssertEqual(recorder.observedSteps, 1)
            try assertReplay(recorder.snapshot())
        }
    }

    func testMissingTurnFreezesPrefixEvenWhenDiagnosticStreamIsContinuous() throws {
        let probe = Probe(), model = probe.model(), initial = try checkInitial(model, state: 4)
        let recorder = try Recorder(checkedInitial: initial, sequenceOrigin: 10, config: config, options: RecorderOptions(maxSteps: 1))
        let log = try logger()
        var state = 4
        let first = try probe.execute(model, state: &state, input: 1, sequence: 11)
        try recorder.observeChecked(first)
        try log.observe(model, event: integrationEvent(first))
        let prefix = recorder.snapshot()
        let omitted = try probe.execute(model, state: &state, input: 1, sequence: 12)
        try log.observe(model, event: integrationEvent(omitted))
        let later = try probe.execute(model, state: &state, input: 1, sequence: 13)
        try log.observe(model, event: integrationEvent(later))
        XCTAssertTrue(later.fullChecking)
        XCTAssertFalse(later.checks.contains { $0.status == .skipped })
        XCTAssertThrowsError(try recorder.observeChecked(later)) { error in
            XCTAssertTrue(String(describing: error).contains("sequence is missing or reordered"))
        }
        let frozen = recorder.snapshot()
        assertSamePrefix(frozen, prefix)
        XCTAssertEqual(recorder.observedSteps, 1)
        XCTAssertEqual(recorder.evictedSteps, 0)
        XCTAssertThrowsError(try recorder.observeChecked(omitted))
        try recorder.stopWithError(ModelError("later diagnostic error"))
        XCTAssertEqual(recorder.snapshot(), frozen)
        XCTAssertEqual(try text(log).split(separator: "\n").count, 3)
        XCTAssertEqual(probe.work, [0, 3, 4, 3, 6])
        try assertReplay(frozen) // Only one turn is exact; no claim for the gap.
    }

    func testCodecFailuresPublishNoPartialRecordAndRecoverWithSameToken() throws {
        let faults: [(String, TextObservationError.Stage)] = [("input", .encodeInput), ("output", .encodeOutput), ("state", .encodeState)]
        for (fault, stage) in faults {
            let probe = Probe(), model = probe.model(), initial = try checkInitial(model, state: 4)
            let recorder = try Recorder(checkedInitial: initial, config: config, options: RecorderOptions(maxSteps: 1))
            let log = try logger()
            try log.observe(model, event: .checkpoint(sequence: 0, state: try initial.state, checks: initial.checks))
            var state = 4
            let token = try probe.execute(model, state: &state, input: 1, sequence: 1)
            try recorder.observeChecked(token)
            let prefix = recorder.snapshot(), delivered = try log.getRef().bytes, work = probe.work
            probe.encodeFailure = fault
            assertStage(stage) { try log.observe(model, event: integrationEvent(token)) }
            XCTAssertEqual(try log.getRef().bytes, delivered)
            XCTAssertFalse(log.isPoisoned)
            XCTAssertEqual(recorder.snapshot(), prefix)
            XCTAssertEqual(probe.work, work)
            probe.encodeFailure = nil
            try log.observe(model, event: integrationEvent(token)) // Same checked result; no retry of application work.
            XCTAssertEqual(probe.work, work)
            XCTAssertEqual(recorder.snapshot(), prefix)
            XCTAssertTrue(try text(log).contains("event=transition sequence=1"))
            let next = try probe.execute(model, state: &state, input: 1, sequence: 2)
            try recorder.observeChecked(next)
            try log.observe(model, event: integrationEvent(next))
            XCTAssertEqual(recorder.observedSteps, 2)
            XCTAssertEqual(recorder.evictedSteps, 1)
            XCTAssertEqual(probe.work, [0, 2, 3, 2, 4])
            try assertReplay(recorder.snapshot())
        }
    }

    func testFormatterFailuresAndSwallowedOverflowPreserveFirstPropertyFailure() throws {
        let faults: [(String, TextObservationError.Stage)] = [("input", .formatInput), ("output", .formatOutput), ("state", .formatState), ("swallow", .record)]
        for (faultName, stage) in faults {
            let probe = Probe(failAt: 5), model = probe.model(), initial = try checkInitial(model, state: 4)
            let recorder = try Recorder(checkedInitial: initial, config: config, options: RecorderOptions(maxSteps: 1))
            let fault = ObservationIntegrationFormatFault()
            let log = try TextObserver(writer: ObservationBytes(), streamID: "app", options: ObservationOptions(level: .trace, snapshots: .everyTransition, maxRecordBytes: 1024), payloads: ObservationIntegrationPayloads(fault: fault))
            try log.observe(model, event: .checkpoint(sequence: 0, state: try initial.state, checks: initial.checks))
            var state = 4
            let token = try probe.execute(model, state: &state, input: 1, sequence: 1)
            try recorder.observeChecked(token)
            let failed = recorder.snapshot(), delivered = try log.getRef().bytes, work = probe.work
            XCTAssertEqual(failed.termination, .propertyFailed)
            fault.stage = faultName
            assertStage(stage) { try log.observe(model, event: integrationEvent(token)) }
            XCTAssertEqual(try log.getRef().bytes, delivered)
            XCTAssertFalse(log.isPoisoned)
