    func testSinkWriteAndFlushFailuresPoisonObserverWithoutReplacingRecorderFailure() throws {
        for flushFailure in [false, true] {
            let probe = Probe(failAt: 6), model = probe.model(), initial = try checkInitial(model, state: 4)
            let recorder = try Recorder(checkedInitial: initial, config: config, options: RecorderOptions(maxSteps: 1))
            let writer = ObservationIntegrationFailingWriter()
            let log = try TextObserver(writer: writer, streamID: "app", options: ObservationOptions(level: .trace, snapshots: .everyTransition), payloads: EncodedPayloads<Int, Int, Int>(maxBlobBytes: 4))
            var state = 4
            let first = try probe.execute(model, state: &state, input: 1, sequence: 1)
            try recorder.observeChecked(first)
            try log.observe(model, event: integrationEvent(first))
            let token = try probe.execute(model, state: &state, input: 1, sequence: 2)
            try recorder.observeChecked(token)
            let failed = recorder.snapshot()
            XCTAssertEqual(failed.termination, .propertyFailed)
            XCTAssertEqual(failed.initialChecks, [.passed("state-5")])
            if flushFailure {
                try log.observe(model, event: integrationEvent(token))
                writer.failFlush = true
                let delivered = writer.bytes
                assertStage(.flush) { try log.flush() }
                XCTAssertEqual(writer.bytes, delivered)
            } else {
                let delivered = writer.bytes
                writer.failAfter = delivered.count + 7
                assertStage(.write) { try log.observe(model, event: integrationEvent(token)) }
                XCTAssertEqual(Array(writer.bytes.prefix(delivered.count)), delivered)
                XCTAssertEqual(writer.bytes.count, delivered.count + 7)
            }
            XCTAssertTrue(log.isPoisoned)
            log.setLevel(.off)
            let calls = [writer.writes, writer.flushes], encodes = probe.encodes
            assertStage(.poisoned) { try log.observe(model, event: integrationEvent(token)) }
            assertStage(.poisoned) { try log.flush() }
            XCTAssertEqual([writer.writes, writer.flushes], calls)
            XCTAssertEqual(probe.encodes, encodes)
            try recorder.stopWithError(ModelError("diagnostic sink failed"))
            XCTAssertEqual(recorder.snapshot(), failed)
            let later = try probe.execute(model, state: &state, input: 0, sequence: 3)
            XCTAssertThrowsError(try recorder.observeChecked(later))
            // A replacement diagnostic sink can report a later failed+skipped
            // event. Error wins, and the exact recorder still retains first failure.
            let recovered = try logger(.warn)
            try recovered.observe(model, event: integrationEvent(later))
            let message = try text(recovered)
            XCTAssertTrue(message.hasPrefix("Error "))
            XCTAssertTrue(message.contains("state.bound\":Failed"))
            XCTAssertTrue(message.contains("edge.optional\":Skipped"))
            XCTAssertEqual(recorder.snapshot(), failed)
            XCTAssertEqual(probe.work, [0, 3, 4, 3, 4])
            try assertReplay(failed, failAt: 6, failure: true)
        }
    }

    func testInitialPropertyFailureUsesOneCheckAndSurvivesObserverFailure() throws {
        let probe = Probe(failAt: 4), model = probe.model(), initial = try checkInitial(model, state: 4)
        let recorder = try Recorder(checkedInitial: initial, sequenceOrigin: 99, config: config, options: RecorderOptions(maxSteps: 1))
        let log = try logger(.error)
        try log.observe(model, event: .checkpoint(sequence: 99, state: try initial.state, checks: initial.checks))
        XCTAssertTrue(try text(log).hasPrefix("Error "))
        XCTAssertEqual(probe.work, [0, 0, 1, 0, 0])
        XCTAssertEqual(probe.encodes, [0, 0, 1])
        let failed = recorder.snapshot()
        XCTAssertEqual(failed.termination, .propertyFailed)
        XCTAssertEqual(failed.initialChecks, initial.checks)
        XCTAssertEqual(failed.steps.count, 0)
        log.setLevel(.trace)
        probe.encodeFailure = "state"
        assertStage(.encodeState) { try log.observe(model, event: .checkpoint(sequence: 99, state: try initial.state, checks: initial.checks)) }
        try recorder.stopWithError(ModelError("initial observer error"))
        XCTAssertEqual(recorder.snapshot(), failed)
        XCTAssertEqual(probe.work, [0, 0, 1, 0, 0])
        probe.encodeFailure = nil
        try assertReplay(failed, failAt: 4, failure: true)
    }

    func testDiagnosticForgeryCannotReplaceAuthenticatedFailedChecks() throws {
        let probe = Probe(failAt: 5), model = probe.model(), initial = try checkInitial(model, state: 4)
        let recorder = try Recorder(checkedInitial: initial, config: config, options: RecorderOptions(maxSteps: 1))
        let log = try logger()
        var state = 4
        let token = try probe.execute(model, state: &state, input: 1, sequence: 1)
        let authentic = try token.observation()
        let forged = TurnObservation(sequence: authentic.sequence, before: authentic.before, input: authentic.input,
                                     transition: authentic.transition, checks: [.passed("forged")], stateCheckCount: 1)
        let event: Event<Int, Int, Int> = .transition(sequence: try ObservationSequence(forged.sequence), before: forged.before,
                                                     input: forged.input, transition: forged.transition, checks: forged.checks)
        let prefix = recorder.snapshot(), work = probe.work
        try log.observe(model, event: event)
        XCTAssertEqual(recorder.snapshot(), prefix)
        XCTAssertNil((forged as Any) as? CheckedTurn<Int, Int, Int>)
        XCTAssertNil((event as Any) as? CheckedTurn<Int, Int, Int>)
        // STATIC COMPILE GUARDS (not executed here): Recorder.observeChecked(event)
        // and Recorder.observeChecked(forged) must fail type checking; direct
        // CheckedTurn(...) construction is private in CheckedResults.swift.
        // A separate expected-compilation-failure consumer is still required to
        // qualify these source-enforced boundaries; runtime casts are narrower.
        try recorder.observeChecked(token)
        try log.observe(model, event: integrationEvent(token))
        XCTAssertEqual(probe.work, work)
        XCTAssertEqual(recorder.snapshot().steps[0].checks, token.checks)
        XCTAssertEqual(recorder.termination, .propertyFailed)
        XCTAssertTrue(try text(log).contains("check=\"forged\":Passed"))
        XCTAssertTrue(try text(log).contains("check=\"state.bound\":Failed(\"bound reached\")"))
        try assertReplay(recorder.snapshot(), failAt: 5, failure: true)
    }

    func testActualApplicationOutputAndDispositionRemainEvidenceWhenReplayDisagrees() throws {
        let probe = Probe(), model = probe.model(), initial = try checkInitial(model, state: 4)
        let recorder = try Recorder(checkedInitial: initial, sequenceOrigin: 11, config: config, options: RecorderOptions(maxSteps: 1))
        let log = try logger()
        // Application integration can produce different outputs from its pure
        // model. Execute that application path exactly once, then certify and
        // observe the supplied result without silently correcting it.
        var application = model
        application.step = { state, input in
            probe.reducerCalls += 1
            return Transition(state: state + input, outputs: [99, 100], disposition: .ignored("host result"))
        }
        let actual = try application.step(4, 1)
        for output in actual.outputs { probe.effectCalls += 1; probe.effects.append(output) }
        let token = try checkTurn(model, before: 4, input: 1, transition: actual, sequence: 12)
        let work = probe.work
        try recorder.observeChecked(token)
        try log.observe(model, event: integrationEvent(token))
        XCTAssertEqual(probe.work, work)
        XCTAssertEqual(probe.work, [0, 1, 2, 1, 2])
        XCTAssertEqual(probe.effects, [99, 100])
        let trace = recorder.snapshot()
        XCTAssertEqual(trace.steps[0].outputs, [Probe.bytes(99), Probe.bytes(100)])
        XCTAssertEqual(trace.steps[0].disposition, .ignored("host result"))
        XCTAssertEqual(trace.steps[0].checks, [.passed("state-5"), .failed("edge.outputs", "unexpected application outputs")])
        XCTAssertEqual(try text(log), "Error stream=\"app\" event=transition sequence=12 disposition=Ignored(\"host result\") outputs=2 checks=2 check=\"state-5\":Passed check=\"edge.outputs\":Failed(\"unexpected application outputs\") input=hex:01000000 output[0]=hex:63000000 output[1]=hex:64000000 post_state=hex:05000000\n")
        let playback = Probe()
        let report = try replayWithObservationsBounded(playback.model(), trace: trace) { observation, _ in
            if case let .turn(value) = observation {
                XCTAssertTrue(value.differences.outputs)
                XCTAssertTrue(value.differences.disposition)
                XCTAssertTrue(value.differences.checks)
            }
        }
        XCTAssertEqual(report.outcome, "diverged")
        XCTAssertEqual(report.step, 1)
        XCTAssertEqual(report.field, "disposition")
        XCTAssertEqual(report.stepsVerified, 0)
        XCTAssertFalse(report.failureReproduced)
        XCTAssertEqual(playback.work, [0, 1, 2, 1, 0])
    }
}
